'use strict';

// MODULES //

var dtypes = require( '@stdlib/ndarray/dtypes' );
var drfftf = require( '@stdlib/fft/base/fftpack/ndarray/float64/rfftf' );
var srfftf = require( '@stdlib/fft/base/fftpack/ndarray/float32/rfftf' );
var grfftf = require( '@stdlib/fft/base/fftpack/ndarray/generic/rfftf' );
var factory = require( '@stdlib/ndarray/base/nullary-strided1d-dispatch-factory' );


// VARIABLES //

var idtypes0 = dtypes( 'real_floating_point_and_generic' );
var odtypes = dtypes( 'real_floating_point_and_generic' );
var table = {
	'types': [
		'float64',
		'float32'
	],
	'fcns': [
		drfftf,
		srfftf
	],
	'default': grfftf
};


// MAIN //

/**
* Computes the forward discrete Fourier transform of a real-valued ndarray in-place using FFTPACK.
*
* @private
* @name rfftf
* @type {Function}
* @param {ndarray} r - working buffer ndarray (modified in-place)
* @param {ndarray} workspace - pre-initialized workspace ndarray
* @param {Options} [options] - function options
* @param {IntegerArray} [options.dims] - list of dimensions over which to perform operation
* @throws {TypeError} first argument must be an ndarray-like object
* @throws {TypeError} second argument must be an ndarray-like object
* @throws {TypeError} options argument must be an object
* @throws {RangeError} dimension indices must not exceed input ndarray bounds
* @throws {RangeError} number of dimension indices must not exceed the number of input ndarray dimensions
* @throws {Error} must provide valid options
* @returns {ndarray} working buffer ndarray
*
* @example
* var zeros = require( '@stdlib/ndarray/zeros' );
* var rffti = require( '@stdlib/fft/fftpack/rffti' );
*
* var r = zeros( [ 4 ], {
*     'dtype': 'float64'
* });
* var ws = rffti( 4 );
*
* var out = rfftf( r, ws );
* // returns <ndarray>
*/
var rfftf = factory( table, [ idtypes0 ], odtypes );


// EXPORTS //

module.exports = rfftf;
